### 🟠 Fix 4: ARIA Live-Region für Warenkorb-Feedback

```html
<!-- Im übergeordneten Layout, einmalig platzieren -->
<div
  role="status"
  aria-live="polite"
  aria-atomic="true"
  class="sr-only"
  id="cart-status"
>
  <!-- Wird per JS befüllt -->
</div>
```

```javascript
// ✅ Screen-Reader-Feedback nach Warenkorb-Aktion
document.querySelector('.add-to-cart').addEventListener('click', async () => {
  const statusEl = document.getElementById('cart-status');

  try {
    await addToCart(productId); // API-Call

    // Nachricht setzen — aria-live="polite" liest sie beim nächsten Pause vor
    statusEl.textContent = 'Nike Air Max wurde dem Warenkorb hinzugefügt.';
  } catch {
    // role="alert" für Fehler (unterbricht sofort)
    statusEl.setAttribute('role', 'alert');
    statusEl.textContent = 'Fehler: Nike Air Max konnte nicht hinzugefügt werden.';
  }

  // Nachricht nach Vorlesen zurücksetzen
  setTimeout(() => {
    statusEl.textContent = '';
    statusEl.setAttribute('role', 'status');
  }, 5000);
});
```

